"use strict";(globalThis.webpackChunkdocs_site=globalThis.webpackChunkdocs_site||[]).push([[8692],{4599(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"category","label":"Getting Started","items":[{"type":"link","href":"/ContextCore/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/ContextCore/docs/getting-started/quick-start","label":"Quick Start","docId":"getting-started/quick-start","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Core Concepts","items":[{"type":"link","href":"/ContextCore/docs/core-concepts/four-tier-memory","label":"Four-Tier Memory","docId":"core-concepts/four-tier-memory","unlisted":false},{"type":"link","href":"/ContextCore/docs/core-concepts/token-budgeting","label":"Token Budgeting","docId":"core-concepts/token-budgeting","unlisted":false},{"type":"link","href":"/ContextCore/docs/core-concepts/sessions","label":"Sessions","docId":"core-concepts/sessions","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Architecture","items":[{"type":"link","href":"/ContextCore/docs/architecture/overview","label":"Architecture Overview","docId":"architecture/overview","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Guides","items":[{"type":"link","href":"/ContextCore/docs/guides/configuring-agent-context","label":"Configuring AgentContext","docId":"guides/configuring-agent-context","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/building-context-windows","label":"Building Context Windows","docId":"guides/building-context-windows","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/memory-management","label":"Memory Management","docId":"guides/memory-management","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/progressive-compression","label":"Progressive Compression","docId":"guides/progressive-compression","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/session-persistence","label":"Session Persistence","docId":"guides/session-persistence","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/custom-embedding-providers","label":"Custom Embedding Providers","docId":"guides/custom-embedding-providers","unlisted":false},{"type":"link","href":"/ContextCore/docs/guides/custom-token-counters","label":"Custom Token Counters","docId":"guides/custom-token-counters","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Metal Engine","items":[{"type":"link","href":"/ContextCore/docs/metal-engine/gpu-scoring","label":"GPU Scoring","docId":"metal-engine/gpu-scoring","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"API Reference","items":[{"type":"link","href":"/ContextCore/docs/api-reference/agent-context","label":"AgentContext","docId":"api-reference/agent-context","unlisted":false},{"type":"link","href":"/ContextCore/docs/api-reference/context-configuration","label":"ContextConfiguration","docId":"api-reference/context-configuration","unlisted":false},{"type":"link","href":"/ContextCore/docs/api-reference/context-window","label":"ContextWindow","docId":"api-reference/context-window","unlisted":false},{"type":"link","href":"/ContextCore/docs/api-reference/turn","label":"Turn","docId":"api-reference/turn","unlisted":false},{"type":"link","href":"/ContextCore/docs/api-reference/memory-chunk","label":"MemoryChunk","docId":"api-reference/memory-chunk","unlisted":false},{"type":"link","href":"/ContextCore/docs/api-reference/protocols","label":"Protocols","docId":"api-reference/protocols","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Performance","items":[{"type":"link","href":"/ContextCore/docs/performance/benchmarks","label":"Benchmarks","docId":"performance/benchmarks","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/ContextCore/docs/faq","label":"FAQ","docId":"faq","unlisted":false}]},"docs":{"api-reference/agent-context":{"id":"api-reference/agent-context","title":"AgentContext","description":"AgentContext is the primary public actor and entry point for ContextCore. It manages sessions, memory, context window construction, and state persistence.","sidebar":"docsSidebar"},"api-reference/context-configuration":{"id":"api-reference/context-configuration","title":"ContextConfiguration","description":"ContextConfiguration controls all tunable parameters for an AgentContext instance.","sidebar":"docsSidebar"},"api-reference/context-window":{"id":"api-reference/context-window","title":"ContextWindow","description":"ContextWindow is the output of AgentContext.buildWindow(currentTask). It contains an ordered list of chunks packed within a token budget, ready for injection into a model prompt.","sidebar":"docsSidebar"},"api-reference/memory-chunk":{"id":"api-reference/memory-chunk","title":"MemoryChunk","description":"MemoryChunk represents a stored piece of memory in ContextCore\'s episodic or semantic memory indices. Returned by AgentContext.recall(query).","sidebar":"docsSidebar"},"api-reference/protocols":{"id":"api-reference/protocols","title":"Protocols","description":"ContextCore defines three public protocols for dependency injection. Each has a built-in default implementation, but can be replaced with custom types.","sidebar":"docsSidebar"},"api-reference/turn":{"id":"api-reference/turn","title":"Turn","description":"Turn represents a single conversation turn appended to an AgentContext session.","sidebar":"docsSidebar"},"architecture/overview":{"id":"architecture/overview","title":"Architecture Overview","description":"ContextCore is a Swift framework that provides GPU-accelerated context window management for LLM-powered agents. It retrieves, scores, compresses, and packs memory chunks into token-budgeted context windows using Metal compute shaders.","sidebar":"docsSidebar"},"core-concepts/four-tier-memory":{"id":"core-concepts/four-tier-memory","title":"Four-Tier Memory","description":"ContextCore organizes an agent\'s knowledge into four distinct memory tiers, each with its own storage semantics, retrieval strategy, and lifecycle. These tiers are represented by the MemoryType enum.","sidebar":"docsSidebar"},"core-concepts/sessions":{"id":"core-concepts/sessions","title":"Sessions","description":"A session represents the lifecycle of a single conversation. It provides the structure within which turns are appended, context windows are built, and knowledge is consolidated.","sidebar":"docsSidebar"},"core-concepts/token-budgeting":{"id":"core-concepts/token-budgeting","title":"Token Budgeting","description":"Every call to buildWindow() must fit within a token budget. ContextCore provides fine-grained control over how that budget is allocated and what happens when space runs out.","sidebar":"docsSidebar"},"faq":{"id":"faq","title":"FAQ","description":"Does ContextCore require a GPU?","sidebar":"docsSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Requirements","sidebar":"docsSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick Start","description":"This guide walks through the core ContextCore flow: initialize, manage a session, build a context window, and interact with long-term memory.","sidebar":"docsSidebar"},"guides/building-context-windows":{"id":"guides/building-context-windows","title":"Building Context Windows","description":"The primary output of ContextCore is a ContextWindow -- a token-budgeted, relevance-ordered collection of chunks ready to be sent to an LLM. You build one by calling buildWindow on an AgentContext instance.","sidebar":"docsSidebar"},"guides/configuring-agent-context":{"id":"guides/configuring-agent-context","title":"Configuring AgentContext","description":"AgentContext is configured through a ContextConfiguration value passed at initialization. Every parameter has a sensible default, so you only need to override what matters for your use case.","sidebar":"docsSidebar"},"guides/custom-embedding-providers":{"id":"guides/custom-embedding-providers","title":"Custom Embedding Providers","description":"ContextCore uses embeddings for retrieval, similarity scoring, compression, and deduplication. You can replace the default on-device provider with any embedding backend.","sidebar":"docsSidebar"},"guides/custom-token-counters":{"id":"guides/custom-token-counters","title":"Custom Token Counters","description":"Token counting drives budget allocation, packing decisions, and compression targeting in ContextCore. You can replace the default heuristic counter with a precise tokenizer for your target model.","sidebar":"docsSidebar"},"guides/memory-management":{"id":"guides/memory-management","title":"Memory Management","description":"AgentContext provides a simple API for storing, retrieving, and managing memories across episodic and semantic stores.","sidebar":"docsSidebar"},"guides/progressive-compression":{"id":"guides/progressive-compression","title":"Progressive Compression","description":"When the token budget is tight and all retrieved candidates cannot fit, ContextCore applies progressive compression to maximize the information density of the context window. This is handled automatically during buildWindow -- no manual invocation is needed.","sidebar":"docsSidebar"},"guides/session-persistence":{"id":"guides/session-persistence","title":"Session Persistence","description":"ContextCore supports checkpointing and restoring full agent state, allowing sessions to survive app restarts, device reboots, or migration between devices.","sidebar":"docsSidebar"},"metal-engine/gpu-scoring":{"id":"metal-engine/gpu-scoring","title":"GPU Scoring","description":"ContextCore accelerates context scoring on-device using Apple Metal compute shaders. All scoring runs on the GPU, keeping latency low even at high chunk counts.","sidebar":"docsSidebar"},"performance/benchmarks":{"id":"performance/benchmarks","title":"Benchmarks","description":"All benchmarks measured on an M2 Max running macOS 26.0, with embedding dimension 384.","sidebar":"docsSidebar"}}}}')}}]);